const $=s=>document.querySelector(s);const escapeHTML=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let products=[];
const productById=id=>products.find(p=>String(p.id)===String(id));
const productImage=p=>p.image||`/assets/${p.art}.png`;
const productPrice=p=>p?.price==null?'Price coming soon':new Intl.NumberFormat('en-GB',{style:'currency',currency:p.currency||'GBP'}).format(p.price/100);
const linePrice=(p,count)=>p?.price==null?'Price coming soon':new Intl.NumberFormat('en-GB',{style:'currency',currency:p.currency||'GBP'}).format(p.price*count/100);
function bagTotal(){if(bag.some(b=>productById(b.id)?.price==null))return 'Prices to be confirmed';return new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP'}).format(bag.reduce((sum,b)=>sum+productById(b.id).price*b.qty,0)/100);}
let bag=JSON.parse(localStorage.getItem('tsoie-bag')||'[]'),category='All',sort='Featured',shade=0,qty=1;const nav=[['Home','/'],['Shop','/shop'],['Formula','/formula'],['About','/about'],['FAQs','/faqs'],['Contact','/contact']];const eyebrow=t=>`<div class="eyebrow">${escapeHTML(t)}</div>`;const button=(t,to,cls='')=>`<a class="btn ${cls}" href="#${to}">${t}</a>`;const tile=(mini,title,copy,cls='')=>`<div class="tile ${cls}"><div class="mini">${mini}</div><h3>${title}</h3><p>${copy}</p></div>`;const card=p=>`<a class="card" href="#/product/${p.id}"><div class="product-art"><img src="${productImage(p)}" alt="${escapeHTML(p.name)}" loading="lazy">${p.badge?`<span class="badge">${escapeHTML(p.badge)}</span>`:''}</div><div class="product-info"><h3>${escapeHTML(p.name)}</h3><div class="price">${productPrice(p)}</div><p>${escapeHTML(p.shortDescription)}</p></div></a>`;const cards=ps=>`<div class="grid">${ps.filter(Boolean).map(card).join('')}</div>`;const details=(q,a)=>`<details><summary>${q}</summary><p>${a}</p></details>`;const intro=(e,h,p,extra='')=>`<section class="intro">${eyebrow(e)}<h1>${h}</h1><p>${p}</p>${extra}</section>`;const feature=(e,h,p,link,text)=>`<div class="feature">${eyebrow(e)}<h2>${h}</h2><p>${p}</p>${button(text,link,'light')}</div>`;
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',4200)}function saveBag(){localStorage.setItem('tsoie-bag',JSON.stringify(bag));$('#bag-count').textContent=`Bag (${bag.reduce((a,b)=>a+b.qty,0)})`}function openDialog(html){$('#dialog-body').innerHTML=html;$('#dialog').showModal()}function accountDialog(){openDialog(`${eyebrow('Your account')}<h2>Welcome to TSOIE</h2><p>Customer accounts are not yet connected for this concept website. For order support, contact customer care.</p>${button('Contact customer care','/contact','primary')}`)}function searchDialog(){openDialog(`<h2>Search TSOIE</h2><input id="site-search" placeholder="Search products" aria-label="Search products" oninput="searchProducts(this.value)"><div id="search-results" class="space"></div>`);searchProducts('');$('#site-search').focus()}function searchProducts(q){$('#search-results').innerHTML=products.filter(p=>p.name.toLowerCase().includes(q.toLowerCase())).map(p=>`<p><a href="#/product/${p.id}" onclick="$('#dialog').close()">${escapeHTML(p.name)} →</a></p>`).join('')||'<p>No matching products. Try “lip” or “skin”.</p>'}
function home(){return `<section class="hero"><div class="hero-copy">${eyebrow('TSOIE Beauty')}<h1>Luxury, refined.<br>Performance,<br>felt.</h1><p>Modern makeup created for an elevated application experience, polished finishes and confident everyday wear.</p><div class="actions">${button('Shop the Collection','/shop','primary')}${button('Discover the Formula','/formula')}</div><div class="chips"><span class="chip">Worldwide delivery</span><span class="chip">Secure checkout</span><span class="chip">Premium formulation</span></div></div><div class="hero-art" role="img" aria-label="TSOIE gold and brown makeup collection"></div></section><section class="wrap"><div class="section-head"><div>${eyebrow('The edit')}<h2>New &<br>noteworthy</h2></div>${button('Shop all products','/shop')}</div>${cards(products.slice(0,3))}</section><section class="dark"><div class="wrap split standard"><div>${eyebrow('The TSOIE standard')}<h2>Made to look beautiful.<br>Designed to perform.</h2><p>A luxury experience should start before the first application and last beyond the final look. TSOIE pairs refined textures, thoughtful formulation and elevated presentation.</p>${button('Explore our formula','/formula','gold full')}</div><div class="tiles">${tile('01 · PERFORMANCE','Long-wear confidence','Product-first design focused on how makeup feels, applies and lasts.','gold')}${tile('02 · EXPERIENCE','Elevated application','Premium details that make daily beauty feel considered.')}${tile('03 · CLARITY','Ingredients explained','Clear product information, usage guidance and formulation detail.')}${tile('04 · TRUST','Made for online confidence','Secure checkout, transparent delivery and easy customer care.','gold')}</div></div></section><section class="wrap">${feature('Formula focus','What goes into the<br>finish matters.','Explore ingredient stories, texture notes, application guidance and the choices behind each formula.','/formula','Learn about formulation')}</section><section class="wrap trust">${[['✓','Worldwide ordering','International shipping options shown clearly at checkout.'],['◇','Secure payments','Built for trusted card and local payment options.'],['↺','Clear support','Shipping, returns and customer care information easy to find.']].map(x=>`<div><h3>${x[0]}　${x[1]}</h3><p>${x[2]}</p></div>`).join('')}</section>`}
function shop(){return intro('Shop TSOIE','The Collection','A curated edit of premium makeup designed for polished colour, lasting performance and an elevated everyday ritual.')+`<section class="wrap shopwrap"><div class="toolbar"><div class="chips">${['All','Lips','Complexion','Eyes','Sets'].map(c=>`<button class="chip ${category===c?'active':''}" onclick="category='${c}';renderShop()">${c}</button>`).join('')}</div><div class="chips"><button class="chip" onclick="$('#filters').hidden=!$('#filters').hidden">Filter +</button><select aria-label="Sort products" onchange="sort=this.value;renderShop()"><option ${sort==='Featured'?'selected':''}>Featured</option><option ${sort==='Name A–Z'?'selected':''}>Name A–Z</option><option ${sort==='Name Z–A'?'selected':''}>Name Z–A</option></select></div></div><div id="filters" class="filter-panel" hidden><label><input type="checkbox" id="new-filter" onchange="drawProducts()"> New arrivals only</label></div><div id="product-grid"></div><button class="btn full load" onclick="toast('You’ve viewed the full collection.')">Load more</button></section><section class="sand"><div class="wrap split finish"><div>${eyebrow('Need a starting point?')}<h2>Find your finish</h2><p>Browse by finish, texture or look. The shop should help customers understand what each product does before they reach checkout.</p><button class="btn primary full" onclick="location.hash='/formula'">Explore by finish</button></div><div class="tiles">${tile('FINISH','Soft matte','')}${tile('FINISH','Satin glow','')}${tile('TEXTURE','Weightless','')}${tile('LOOK','High impact','')}</div></div></section>`}function renderShop(){render(false)}function drawProducts(){let ps=products.filter(p=>(category==='All'||p.category===category)&&(!$('#new-filter')?.checked||p.badge==='NEW'));if(sort!=='Featured')ps.sort((a,b)=>sort==='Name A–Z'?a.name.localeCompare(b.name):b.name.localeCompare(a.name));$('#product-grid').innerHTML=ps.length?cards(ps):'<div class="empty"><h3>Coming soon</h3><p>This category has no products in the current collection.</p><button class="btn" onclick="category=\'All\';renderShop()">View all products</button></div>'}
function product(id){const p=productById(id);if(!p)return `<section class="wrap empty"><h1>Product unavailable</h1><p>This product is no longer in the collection.</p>${button('Explore the collection','/shop','primary')}</section>`;return `<section class="wrap" style="padding-top:50px;padding-bottom:60px"><div class="breadcrumb"><a href="#/">Home</a> / <a href="#/shop">Shop</a> / ${escapeHTML(p.category)} / ${escapeHTML(p.name)}</div><div class="product-layout"><div class="gallery"><img src="${p.id==='0'&&p.image==='/assets/lip.png'?'/assets/detail0.png':productImage(p)}" alt="${escapeHTML(p.name)} front view"><img src="${p.id==='0'&&p.image==='/assets/lip.png'?'/assets/detail1.png':productImage(p)}" alt="${escapeHTML(p.name)} detail"><div class="texture">${eyebrow('Texture view')}<h2>Rich colour.<br>Refined<br>feel.</h2></div><img src="assets/detail2.png" alt="Colour texture sample"></div><div class="product-description">${eyebrow(p.category)}<h1>${escapeHTML(p.name)}</h1><div class="row"><span>${productPrice(p)}</span><span class="small">New · Reviews coming soon</span></div><p>${escapeHTML(p.description)}</p><div class="mini">SHADE · SAMPLE <span id="shade-name"></span></div><div class="swatches">${['#843332','#a25f57','#ba8074','#722e2a','#a55b3e'].map((c,i)=>`<button aria-label="Select sample shade ${i+1}" aria-pressed="${i===shade}" class="swatch ${i===shade?'active':''}" style="background:${c}" onclick="selectShade(${i},this)"></button>`).join('')}</div><div class="quantity"><span>Quantity</span><div><button aria-label="Decrease quantity" onclick="qty=Math.max(1,qty-1);$('#quantity').textContent=qty">−</button><span id="quantity">${qty}</span><button aria-label="Increase quantity" onclick="qty++;$('#quantity').textContent=qty">+</button></div></div><button class="btn primary full" ${p.stock===0?'disabled':''} onclick="addBag('${p.id}')">${p.stock===0?'Out of stock':'Add to Bag · '+productPrice(p)}</button><div class="small center" style="margin:14px 0 28px">Secure checkout · Worldwide delivery options</div>${details("Why you'll love it",'A premium colour concept with a smooth glide, elegant payoff and a polished finish. Final product benefits will be confirmed by TSOIE.')}${details('How to use','Final application and storage guidance will be supplied with the confirmed product. Contact customer care for advice.')}${details('Ingredients','Full ingredients (INCI) will be supplied by product and shade once final formulations are confirmed. <a href="#/formula">Explore our formula →</a>')}${details('Shipping & returns','Delivery rates and return eligibility are to be confirmed. <a href="#/shipping">View shipping & returns →</a>')}<div class="support"><div class="mini">PRODUCT SUPPORT</div><p>Need help choosing a shade or understanding the formula? <a href="#/contact">Contact customer care</a> before ordering.</p></div></div></div></section><section class="dark"><div class="wrap"><div class="center">${eyebrow('The experience')}<h2>Application, texture, finish</h2></div><div class="three space">${[['Smooth application','Space for the confirmed performance benefit and application description.'],['Refined finish','Show what the product looks like on skin and what finish the customer can expect.'],['Wear notes','Add validated wear, comfort and testing information once supplied.']].map((x,i)=>`<div><h2 style="color:var(--gold)">0${i+1}</h2><h3>${x[0]}</h3><p style="font-size:12px">${x[1]}</p></div>`).join('')}</div></div></section><section class="wrap"><div class="section-head"><div>${eyebrow('Complete the look')}<h2>Pairs beautifully<br>with</h2></div></div>${cards([products[1],products[2],products[7]])}</section>`}function selectShade(i,el){shade=i;document.querySelectorAll('.swatch').forEach(x=>{x.classList.remove('active');x.setAttribute('aria-pressed','false')});el.classList.add('active');el.setAttribute('aria-pressed','true');$('#shade-name').textContent=i+1}function addBag(id){const product=productById(id);if(!product)return toast('This product is no longer available.');let b=bag.find(p=>String(p.id)===String(id)&&p.shade===shade);const total=bag.filter(p=>String(p.id)===String(id)).reduce((sum,p)=>sum+p.qty,0);if(product.stock!==null&&total+qty>product.stock)return toast('There is not enough stock available for this quantity.');if(b)b.qty+=qty;else bag.push({id:String(id),shade,qty});saveBag();toast('Added to your bag.');}
function formula(){return `<section class="wrap split about-hero"><div>${eyebrow('Formula')}<h1>What goes into<br>the finish<br>matters.</h1><p>This page turns formulation into something customers can understand: what a product is designed to do, how it feels, how to use it and what is inside.</p></div><div class="orb" role="img" aria-label="Golden formula texture"></div></section><section class="wrap three">${tile('01 · PERFORMANCE','Built around the result','Lead with validated product benefits: coverage, finish, wear, feel and ease of application.')}${tile('02 · EXPERIENCE','Texture matters','Explain how the formula moves, blends and sits on the skin in plain language.')}${tile('03 · TRANSPARENCY','Ingredients, explained','Give shoppers enough context to make an informed decision before buying online.')}</section><section class="white"><div class="wrap split" style="align-items:start"><div>${eyebrow('Ingredient glossary')}<h2>Make the formula<br>easy to understand.</h2><p>The live site can list hero ingredients, their purpose and the full INCI list for each product once final formulations are supplied.</p></div><div>${[1,2,3].map(i=>details(`Ingredient / active 0${i}`,'Function and customer-friendly explanation. Final ingredient details are awaiting confirmed formulations.')).join('')}${details('Full ingredients (INCI)','Shown by product and shade where applicable. Full INCI lists will be added once supplied by the brand.')}</div></div></section><section class="wrap"><div class="feature split"><div>${eyebrow('Formulation principles')}<h2>A place for the claims<br>you can stand behind.</h2></div><div class="tiles">${[['TESTING','Add approved testing or quality standards.'],['SUITABILITY','Add skin-type or use guidance supported by product data.'],['CLAIMS','Keep claims specific, clear and evidence-based.'],['TRANSPARENCY','Link every product to complete ingredient information.']].map(x=>`<div style="padding:22px;border:1px solid #ffffff33;border-radius:12px"><div class="mini" style="color:#e7c887">${x[0]}</div><p style="font-size:12px;margin:10px 0 0">${x[1]}</p></div>`).join('')}</div></div></section>`}
function about(){return `<section class="wrap split about-hero"><div>${eyebrow('About TSOIE')}<h1>Beauty with a<br>refined point of<br>view.</h1><p>TSOIE Beauty is a modern luxury makeup brand focused on refined, performance-driven products and an elevated application experience.</p></div><img src="assets/about.png" alt="TSOIE gold-rimmed compact"></section><section class="wrap split about-story"><div>${eyebrow('The point of view')}<h2>Luxury should feel as<br>good as it looks.</h2></div><div><p>The brand story page should explain why TSOIE exists, what it believes beautiful makeup should deliver and how product performance, presentation and customer experience come together.</p><p style="font-size:14px">Founder story, origin, product development journey and verified milestones can be added here once supplied by the brand owner.</p></div></section><section class="sand"><div class="wrap three">${tile('01 · REFINED','Considered design','A visual world that feels modern, calm and unmistakably premium.','dark')}${tile('02 · PERFORMANCE','Product first','Beautiful packaging must be matched by a formula customers want to use again.','gold')}${tile('03 · EXPERIENCE','Every touchpoint counts','From discovery and shade choice to delivery and customer care.')}</div></section><section class="wrap"><div class="feature split"><div>${eyebrow('From Manchester, to the world')}<h2>A UK brand with global reach.</h2><p>The website should be built to support customers discovering TSOIE through social media, search and direct visits, then confidently ordering across markets.</p></div><div class="monogram">T</div></div></section>`}
const questions=[['Products & shades',[['How do I choose the right shade?','Compare the sample shade options on each product page. For personal guidance, contact hello@tsoie.co.uk before ordering.'],['Where can I see product swatches or application results?','The product page includes concept texture and shade views. Verified product swatches and application results will be added once supplied.'],['Where can I find the full ingredient list?','Full INCI information will be shown by product and shade once final formulations are supplied. Visit Formula for more information.'],['How should I use and store my product?','Follow the confirmed guidance supplied with your product. For product-specific advice, contact customer care.']]],['Orders & payments',[['What payment methods do you accept?','Checkout is securely hosted by Stripe. Available card and digital wallet options are shown at checkout. Test mode is clearly labelled and does not charge real money.'],['Can I change or cancel my order?','Contact hello@tsoie.co.uk with your order details. The final change and cancellation policy is to be confirmed.'],['How will I know my order has been confirmed?','After successful payment, the site shows a confirmed order number and total. If confirmation is pending, use Check payment status or contact customer care. Test payments do not place real orders.']]],['Shipping & returns',[['Do you ship internationally?','Worldwide shipping regions, rates and carriers will be shown at the live checkout once confirmed.'],['How long will delivery take?','Delivery estimates and order cut-off times are to be confirmed. See Shipping & Returns for the current information.'],['Will I pay customs or import duties?','Duties and customs arrangements will be confirmed for each supported destination before live checkout.'],['What is your returns policy?','Return eligibility, hygiene restrictions and refund timelines are to be confirmed. Contact customer care before returning any product.']]]];
function faqs(){return intro('Help centre','Frequently asked questions','Clear answers help remove hesitation before checkout, especially for a growing premium brand selling online across markets.','<div class="faqsearch"><input aria-label="Search questions" placeholder="Search questions　⌕" oninput="filterFaqs(this.value)"></div>')+`<section class="wrap side-layout"><aside class="sidebar"><div class="mini">BROWSE BY TOPIC</div>${['Products & shades','Ingredients & formula','Orders & payments','Shipping & delivery','Returns & exchanges','Account & support'].map((s,i)=>`<a href="${i===1?'#/formula':i===5?'#/contact':'#faq-'+(i<2?0:i===2?1:2)}" onclick="${i===1||i===5?'':`event.preventDefault();document.getElementById('faq-${i<2?0:i===2?1:2}').scrollIntoView({behavior:'smooth'})`}">${s}</a>`).join('')}</aside><div>${questions.map((g,i)=>`<section class="faqgroup" id="faq-${i}">${eyebrow(g[0])}${g[1].map(q=>details(...q)).join('')}</section>`).join('')}<p id="faq-empty" hidden>No matching questions. Contact customer care for help.</p></div></section><section class="wrap">${feature('Still need help?','Talk to customer care','For product, order or delivery questions, contact hello@tsoie.co.uk.','/contact','Contact us')}</section>`}function filterFaqs(q){let found=0;document.querySelectorAll('.faqgroup details').forEach(d=>{d.hidden=!d.textContent.toLowerCase().includes(q.toLowerCase());if(!d.hidden)found++});$('#faq-empty').hidden=!!found}
function contact(){return `<section class="wrap contact"><div>${eyebrow('Contact')}<h1>We'd love to<br>hear from you.</h1><p>For product questions, order support, wholesale or general enquiries, send a message and the TSOIE team can respond through the appropriate channel.</p><div class="info"><div class="mini">CUSTOMER CARE</div><p><a href="mailto:hello@tsoie.co.uk">hello@tsoie.co.uk</a></p><div class="mini">BUSINESS ADDRESS</div><p>Whinlatter Close, Middleton<br>Manchester, England, M24 5TA</p><div class="mini">SOCIAL</div><p>Instagram · TikTok · Pinterest</p></div></div><form class="formbox" onsubmit="sendContact(event)"><h2>Send a message</h2><div class="formgrid"><div><label for="first">FIRST NAME</label><input id="first" name="first" autocomplete="given-name" placeholder="Your first name" required></div><div><label for="last">LAST NAME</label><input id="last" name="last" autocomplete="family-name" placeholder="Your last name" required></div></div><label for="email">EMAIL</label><input id="email" name="email" type="email" autocomplete="email" placeholder="name@example.com" required><label for="topic">ENQUIRY TYPE</label><select id="topic" name="topic" required><option value="">Select a topic</option><option>Product questions</option><option>Order support</option><option>Wholesale</option><option>General enquiry</option></select><label for="message">MESSAGE</label><textarea id="message" name="message" placeholder="How can we help?" required></textarea><button class="btn primary full">Send message</button><p class="small" id="contact-status" style="margin:10px 0 0" hidden></p></form></section><section class="sand"><div class="wrap"><div class="center">${eyebrow('Quick help')}<h2>You may find the answer here</h2></div><div class="three space">${[['Shipping','Delivery areas, timing, tracking and customs.','/shipping','View shipping'],['Returns','Return eligibility, process and refund information.','/shipping','View returns'],['Product questions','Shade, formula, ingredients and application guidance.','/faqs','View FAQs']].map(x=>`<a class="tile white" href="#${x[2]}"><h3>${x[0]}</h3><p>${x[1]}</p><div class="small" style="margin-top:18px">${x[3]} →</div></a>`).join('')}</div></div></section>`}function sendContact(e){e.preventDefault();const f=new FormData(e.target),body=`Name: ${f.get('first')} ${f.get('last')}\nEmail: ${f.get('email')}\n\n${f.get('message')}`;location.href=`mailto:hello@tsoie.co.uk?subject=${encodeURIComponent(f.get('topic'))}&body=${encodeURIComponent(body)}`;$('#contact-status').hidden=false;$('#contact-status').textContent='Your email app will open with your message. Send it there to contact TSOIE.'}
function shipping(){return intro('Delivery & care','Shipping & returns','A clear policy page is essential for international customers. Exact prices, delivery times and return conditions should be confirmed before launch.')+`<section class="wrap three">${tile('UK','United Kingdom','Delivery options, order cut-off and estimated timing to be confirmed.')}${tile('INT','International','Worldwide shipping regions, rates and carriers shown at checkout.')}${tile('↺','Returns','Eligibility window, hygiene restrictions and refund process to be confirmed.')}</section><section class="white"><div class="wrap side-layout"><aside class="sidebar"><div class="mini">ON THIS PAGE</div>${['UK delivery','International delivery','Customs & duties','Order tracking','Returns & exchanges','Refunds'].map((t,i)=>`<a href="#policy-${i}" onclick="event.preventDefault();document.getElementById('policy-${i===2?1:i===3?0:i===5?4:i}').scrollIntoView({behavior:'smooth'})">${t}</a>`).join('')}</aside><div class="policy"><div id="policy-0">${eyebrow('UK delivery')}<h3>Delivery information</h3><p>Use a simple table on the live site for shipping method, price, estimated delivery window and any free-shipping threshold.</p><table><thead><tr><th>Method</th><th>Price</th><th>Estimate</th></tr></thead><tbody><tr><td>Standard delivery</td><td>To confirm</td><td>To confirm</td></tr><tr><td>Express delivery</td><td>To confirm</td><td>To confirm</td></tr></tbody></table></div><div id="policy-1">${eyebrow('International delivery')}<p>Show supported countries, carrier options, estimated transit times and whether duties are prepaid or payable on arrival.</p></div><div id="policy-4">${eyebrow('Returns & exchanges')}<p>Cosmetics may have hygiene-related return restrictions. The website should state the confirmed eligibility window, product condition requirements, exclusions and how customers start a return.</p></div><div class="tile dark"><div class="mini" style="color:var(--gold)">IMPORTANT BEFORE LAUNCH</div><p style="margin-top:12px">The brand owner should approve all delivery rates, return periods, hygiene exclusions, customs wording and refund timelines before this page goes live.</p></div></div></div></section>`}
function bagPage(){return `<section class="wrap" style="padding-top:48px;padding-bottom:48px"><div class="bag-intro">${eyebrow('Shopping bag')}<h1>Your bag</h1></div><div class="bag-layout"><div>${bag.length?bag.map((b,i)=>{const p=productById(b.id);if(!p)return `<div class="bag-item"><div><h3>Product unavailable</h3><p>This product is no longer in the collection.</p><button onclick="removeBag(${i})">Remove</button></div></div>`;return `<div class="bag-item"><a href="#/product/${p.id}"><img src="${productImage(p)}" alt="${escapeHTML(p.name)}"></a><div><a href="#/product/${p.id}"><h3>${escapeHTML(p.name)}</h3></a><p>Shade: Sample ${b.shade+1} · Qty ${b.qty}</p><button onclick="removeBag(${i})">Remove</button></div><span class="price">${linePrice(p,b.qty)}</span></div>`}).join(''):`<div class="empty formbox"><h3>Your bag is empty</h3><p>Discover the TSOIE collection.</p>${button('Shop the Collection','/shop','primary')}</div>`}<div class="support"><div class="mini">DELIVERY NOTE</div><p>Shipping options, taxes and any international duties information should be visible before payment.</p></div></div><div class="summary"><h2>Order summary</h2><div class="summary-row"><span>Subtotal</span><span>${bagTotal()}</span></div><div class="summary-row"><span>Shipping</span><span>Calculated next</span></div><div class="summary-row"><span>Estimated total</span><strong>${bagTotal()}</strong></div><form class="discount" onsubmit="event.preventDefault();toast('Discount codes are not active in this concept store.')"><input placeholder="Discount code" aria-label="Discount code" required><button>Apply</button></form><button id="checkout-button" class="btn primary full" ${bag.length?'':'disabled'} onclick="checkout()">Secure checkout</button><p class="small" id="payment-message">Secure payments through Stripe. Delivery and the final total are shown before payment.</p></div></div></section><section class="sand"><div class="wrap">${eyebrow('Checkout experience')}<h2>Simple, trusted and international-ready.</h2><div class="three space">${tile('STEP 1','Contact & delivery','Email, destination, delivery address and shipping method.')}${tile('STEP 2','Payment','Secure card and supported local or wallet payment options.')}${tile('STEP 3','Confirmation','Order number, receipt, delivery estimate and tracking route.')}</div></div></section>`}function removeBag(i){bag.splice(i,1);saveBag();render(false)}let checkoutRunning=false,receiptLoading=false;
async function checkout(){
 if(checkoutRunning||!bag.length)return;
 if(bag.some(b=>!productById(b.id)||productById(b.id).price===null)){toast('Some products do not have a confirmed price yet. Please contact customer care.');return;}
 checkoutRunning=true;const control=document.querySelector('#checkout-button');if(control){control.disabled=true;control.textContent='Opening secure checkout…';}
 try{
  const items=bag.map(b=>({id:String(b.id),quantity:b.qty,shade:b.shade}));
  const fingerprint=JSON.stringify(items.map(i=>({...i,price:productById(i.id)?.price})));
  let attempt;try{attempt=JSON.parse(sessionStorage.getItem('tsoie-checkout-attempt')||'null');}catch{}
  if(!attempt||attempt.fingerprint!==fingerprint){attempt={requestId:crypto.randomUUID(),fingerprint};sessionStorage.setItem('tsoie-checkout-attempt',JSON.stringify(attempt));}
  const response=await fetch('/api/checkout',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({items,requestId:attempt.requestId})});const result=await response.json();
  if(!response.ok){if(response.status===409)sessionStorage.removeItem('tsoie-checkout-attempt');throw new Error(result.error||'Checkout could not be opened.');}
  const destination=new URL(result.url);if(destination.protocol!=='https:'||!['checkout.stripe.com','www.tsoiebeauty.com'].includes(destination.hostname))throw new Error('Checkout could not be opened.');
  window.location.assign(destination.href);
 }catch(e){toast(e.message||'Checkout could not be opened. Please try again.');}
 finally{checkoutRunning=false;if(control){control.disabled=false;control.textContent='Secure checkout';}}
}
function paymentReturn(){return `<section class="wrap"><div class="formbox receipt" id="receipt"><div class="eyebrow">Your order</div><h1>Confirming your payment…</h1><p>Please wait while we securely check your payment with Stripe.</p></div></section>`;}
async function loadOrderReceipt(){
 if(receiptLoading)return;receiptLoading=true;
 try{
  const params=new URLSearchParams(location.hash.split('?')[1]||'');const id=params.get('order'),token=params.get('token');
  const response=await fetch('/api/order?id='+encodeURIComponent(id||'')+'&token='+encodeURIComponent(token||''),{cache:'no-store'});const order=await response.json();if(!response.ok)throw new Error(order.error||'We could not confirm this order.');
  if(!document.querySelector('#receipt'))return;
  if(order.status!=='paid'){document.querySelector('#receipt').innerHTML=`${eyebrow('Payment status')}<h1>${['expired','failed'].includes(order.status)?'Payment not completed':'Payment confirmation pending'}</h1><p>${order.status==='pending'?'Your payment has not yet been confirmed. If you completed payment, check again shortly.':'Your bag has been kept so you can try checkout again.'}</p><button class="btn" onclick="loadOrderReceipt()">Check payment status</button> ${button('Return to bag','/bag','primary')}`;return;}
  let cleared;try{cleared=JSON.parse(localStorage.getItem('tsoie-cleared-orders')||'[]');}catch{cleared=[];}
  if(!cleared.includes(order.id)){
   for(const bought of order.items){let remaining=bought.quantity;for(const entry of bag){if(String(entry.id)===bought.id&&entry.shade===bought.shade){const used=Math.min(entry.qty,remaining);entry.qty-=used;remaining-=used;}}}
   bag=bag.filter(b=>b.qty>0);saveBag();cleared.push(order.id);localStorage.setItem('tsoie-cleared-orders',JSON.stringify(cleared));sessionStorage.removeItem('tsoie-checkout-attempt');
  }
  const format=amount=>new Intl.NumberFormat('en-GB',{style:'currency',currency:order.currency}).format(amount/100);
  document.querySelector('#receipt').innerHTML=`${eyebrow(order.live?'Thank you':'Test payment successful')}<h1>${order.live?'Your payment is confirmed.':'Your test payment is confirmed.'}</h1><p>${order.live?'Thank you for shopping with TSOIE. Keep your order number for customer care.':'No real money was charged and no products will be shipped.'}</p><p><strong>Order ${escapeHTML(order.number)}</strong></p><div class="receipt-lines">${order.items.map(i=>`<div class="summary-row"><span>${escapeHTML(i.name)} · Sample ${i.shade+1} × ${i.quantity}</span><span>${format(i.unitAmount*i.quantity)}</span></div>`).join('')}<div class="summary-row"><span>Delivery</span><span>${format(order.shipping)}</span></div><div class="summary-row"><strong>Total paid</strong><strong>${format(order.total)}</strong></div></div><div class="actions">${button('Continue shopping','/shop','primary')}${button('Contact customer care','/contact')}</div>`;
 }catch(e){if(document.querySelector('#receipt'))document.querySelector('#receipt').innerHTML=`${eyebrow('Order support')}<h1>We could not confirm this order.</h1><p>${escapeHTML(e.message)}</p>${button('Contact customer care','/contact','primary')}`;}
 finally{receiptLoading=false;}
}
async function loadPaymentMessage(){try{const response=await fetch('/api/checkout',{cache:'no-store'});const setup=await response.json();const element=document.querySelector('#payment-message');if(element)element.textContent=!setup.ready?'Checkout is being configured. Please check back shortly.':setup.live?'Secure card and supported digital wallet payments through Stripe.':'TEST MODE · No real money is charged and no products are shipped.';}catch{}}

function footer(){return `<div class="footer-grid"><div><a href="#/" class="logo"><img src="assets/logo-footer.png" alt="TSOIE Beauty" width="117" height="70"></a><p>Modern luxury makeup, refined for elevated everyday wear.</p></div><div><h4>EXPLORE</h4>${nav.slice(1,5).map(x=>`<a href="#${x[1]}">${x[0]}</a>`).join('')}</div><div><h4>HELP</h4><a href="#/contact">Contact</a><a href="#/shipping">Shipping & Returns</a><a href="#/privacy">Privacy</a><a href="#/terms">Terms</a><a href="/admin/">Admin Studio ↗</a></div><div><h4>STAY CLOSE</h4><p>Join the TSOIE list for launches, beauty notes and first access.</p><form class="newsletter" onsubmit="event.preventDefault();openDialog('<h2>Stay close</h2><p>Newsletter signup is not connected yet. Email hello@tsoie.co.uk to register your interest.</p>')"><input type="email" required placeholder="Email address" aria-label="Newsletter email"><button aria-label="Join mailing list">→</button></form><a href="mailto:hello@tsoie.co.uk">hello@tsoie.co.uk</a></div></div><div class="footer-bottom"><span>© TSOIE Ltd · Manchester, England</span><span>Instagram · TikTok · Pinterest</span></div><div class="concept">CONCEPT MOCKUP · PLACEHOLDER PRODUCT CONTENT FOR CLIENT REVIEW</div>`}function render(scroll=true){const path=(location.hash.slice(1)||'/').split('?')[0];$('#nav').innerHTML=nav.map(x=>`<a href="#${x[1]}" class="${path===x[1]||(x[1]==='/shop'&&path.startsWith('/product'))?'active':''}">${x[0]}</a>`).join('');let content;if(path==='/')content=home();else if(path==='/shop')content=shop();else if(path.startsWith('/product/'))content=product(path.split('/')[2]);else if(path==='/formula')content=formula();else if(path==='/about')content=about();else if(path==='/faqs')content=faqs();else if(path==='/contact')content=contact();else if(path==='/shipping')content=shipping();else if(path==='/bag')content=bagPage();else if(path==='/checkout-success')content=paymentReturn();else if(path==='/privacy'||path==='/terms')content=intro('TSOIE Beauty',path==='/privacy'?'Privacy':'Terms','The confirmed policy will be supplied by TSOIE before the store opens for live orders.')+`<section class="wrap center"><p>This concept website stores your bag in your browser. Admin sessions use a secure cookie. Product information and uploaded images are stored securely. Stripe securely processes checkout payments. We store order details for payment confirmation and customer care. Customer accounts, analytics and mailing list subscriptions are not connected.</p>${button('Contact customer care','/contact','primary')}</section>`;else content=home();$('#app').innerHTML=content;$('#footer').innerHTML=footer();saveBag();if(path==='/shop')drawProducts();if(path==='/bag')loadPaymentMessage();if(path==='/checkout-success')loadOrderReceipt();if(scroll)window.scrollTo(0,0);document.title=(path==='/'?'TSOIE Beauty':path.startsWith('/product/')?(productById(path.split('/')[2])?.name||'Product'):path.slice(1).replace(/^./,s=>s.toUpperCase()))+' · TSOIE Beauty'}window.addEventListener('hashchange',()=>{if($('#dialog').open)$('#dialog').close();render()});$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog'))$('#dialog').close()});render();

let catalogVersion=null,catalogRequest=null;
async function refreshCatalog(){
 if(catalogRequest)return catalogRequest;
 catalogRequest=(async()=>{try{
  const response=await fetch('/api/products',{cache:'no-store'});if(!response.ok)throw new Error('Catalogue unavailable');
  const data=await response.json();if(!Array.isArray(data.products))throw new Error('Invalid catalogue');
  if(catalogVersion===data.version)return;catalogVersion=data.version;
  products=data.products;
  const scroll=window.scrollY;render(false);window.scrollTo(0,scroll);
  document.querySelector('#catalog-error')?.remove();
 }catch(error){if(!products.length&&!document.querySelector('#catalog-error')){const banner=document.createElement('div');banner.id='catalog-error';banner.className='catalog-error';banner.textContent='The collection could not be loaded. Please refresh the page to try again.';document.querySelector('#app').prepend(banner);}}finally{catalogRequest=null;}})();return catalogRequest;
}
refreshCatalog();
window.addEventListener('storage',event=>{if(event.key==='tsoie-catalog-updated')refreshCatalog();});
window.addEventListener('focus',refreshCatalog);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshCatalog();});
setInterval(()=>{if(!document.hidden)refreshCatalog();},15000);
